def bill_cao_cap(p):
    o = orders(p, valid=True)
    return int(o[o['revenue'] >= 1000000].shape[0])

def bao_hanh(p):
    o = orders(p, valid=True)
    total = len(o)
    if total == 0:
        raise Unanswerable('Không có đơn hợp lệ trong kỳ')
    count = o[o['warranty']].shape[0]
    return round_half_up(count / total * 100, 2)

def khach_thanh_vien_moi_thang(p):
    reg_date = pd.to_datetime(T['QuanLy_1']['Ngày đăng ký'])
    mask = reg_date.between(p.start, p.end)
