def khach_vip(p, min_orders=4):
    so_don = customer_sales(p, by="n_orders")
    return so_don[so_don >= min_orders].index.tolist()

def so_chi_khe(p):
    o = orders(p)
    plates = o["plate"].dropna()
    return int(plates.nunique())

def phi_ship(p):
    o = orders(p, valid=True)
    if o.empty:
        return 0
    return round_half_up(o['shipping_fee'].sum(), 0)

def khach_no(p, k=None):
    o = orders(p)
    o = o[(o['payment_method'] == 'ghi nợ') & (o['status'] != 'hoàn thành')]
    debt = o.groupby('customer_id')['revenue'].sum()
    debt = debt[debt > 0]
    if k is not None:
        return debt.head(k)
    return debt

def don_gia_tri(p):
    o = orders(p, valid=True)
    return int((o[o['revenue'] >= 430000]).shape[0])

def so_bien_so(p):
    o = orders(p, valid=True)
    if o.empty:
        raise Unanswerable('Kỳ không có đơn hàng')
    return int(o['plate'].nunique())

def khoi_luong_ban(p, item=None, group=None):
    lines_data = lines(p, valid=True, item=item, group=group)
    return int(lines_data['qty_base'].sum())

def gia_ban_ghi(p, item=None):
    l = lines(p)
    if item is not None:
        l = l[l['item_name'] == item]
    return l['unit_price']

def no_dau(p):
    o = C["orders"].copy()
    o = o[p.mask(o["order_date"])]
    if o.empty:
        return 0
    end_day = o["order_date"].max()
    debt = o[o["order_date"] == end_day]["debt_end"].sum()
    return int(debt)

def thoa_lam_nhieu_nhat(p):
    o = orders(p)
    dem = o.groupby('staff')['order_id'].count()
    return dem.idxmax()

def tien_giam_voucher(p):
    o = C["orders"].copy()
    o = o[o["valid"]][p.mask(o["order_date"])]
    return int(o["voucher_discount"].sum())
